test('renderInvoiceText sums multiple lines correctly', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },     // 2 * 8500 = 17000
      { sku: 'DEV-HOUR', qty: 3 },     // 3 * 9500 = 28500
      { sku: 'COPY-HOUR', qty: 1 },    // 1 * 6000 = 6000
    ],
  });

  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');
  const totalLine = lines[lines.length - 1];
  // C-001 is gold tier (5% discount)
  // subtotal: 17000 + 28500 + 6000 = 51500
  // discount: 850 + 1425 + 300 = 2575
  // total: 51500 - 2575 = 48925 = €489.25
  assert(totalLine.includes('€489.25'));
});

