  const vat = lineVAT({ qty: 10, unitPrice: 1000, vatRate: 9 });
  assert.equal(vat, 900);
});

test('lineVAT with 21% VAT rate', () => {
  // Line: 10 * 1000 = 10000, no discount, amount after = 10000
  // VAT 21% = 10000 * 0.21 = 2100
  const vat = lineVAT({ qty: 10, unitPrice: 1000, vatRate: 21 });
  assert.equal(vat, 2100);
});

