      { sku: 'COPY-HOUR', qty: 2 },                        // 12000 - 0 = 12000 (standard tier 0%)
    ],
  });
  const totals = invoiceTotals(result.value);
  // subtotal: 42500 + 28500 + 12000 = 83000
  // discount: 4250 + 5700 + 0 = 9950
  // total: 83000 - 9950 = 73050
  assert.equal(totals.subtotal, 83000);
  assert.equal(totals.discount, 9950);
  assert.equal(totals.total, 73050);
});

