      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // DES-HOUR: 5 * 8500 = 42500, VAT 21% = 8925
