test('removeLine rejects modification of non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', qty: 3, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 },
    ],
  };

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('addLine and removeLine chain together', () => {
  let result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  let invoice = result.value;

  // Add a line
  const add1 = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(add1.ok, true);
  invoice = add1.value;
  assert.equal(invoice.lines.length, 2);

  // Add another
  const add2 = addLine(invoice, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(add2.ok, true);
  invoice = add2.value;
  assert.equal(invoice.lines.length, 3);

  // Remove one
  const remove1 = removeLine(invoice, 'DEV-HOUR');
  assert.equal(remove1.ok, true);
  invoice = remove1.value;
  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
  assert.equal(invoice.lines[1].sku, 'COPY-HOUR');
});

test('issueInvoice sets number and changes status to issued', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);

  const issueResult = issueInvoice(result.value, []);
  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2026-0001');
  assert.equal(issueResult.value.status, 'issued');
});

test('issueInvoice generates next number based on existing numbers', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);

  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const issueResult = issueInvoice(result.value, existing);
  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2026-0003');
});

test('issueInvoice preserves all invoice properties', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(result.ok, true);
  const invoice = result.value;

  const issueResult = issueInvoice(invoice, []);
  assert.equal(issueResult.ok, true);
  const issued = issueResult.value;
  assert.equal(issued.customerId, 'C-001');
  assert.equal(issued.issueDate, '2026-10-07');
  assert.equal(issued.lines.length, 2);
  assert.equal(issued.lines[0].sku, 'DES-HOUR');
  assert.equal(issued.lines[1].sku, 'DEV-HOUR');
});

test('issueInvoice does not mutate the original invoice', () => {
