test('issueInvoice with dates from different years', () => {
  const invoiceA = {
    customerId: 'C-001',
    issueDate: '2025-12-31',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const invoiceB = {
    customerId: 'C-001',
    issueDate: '2026-01-01',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const issueA = issueInvoice(invoiceA, []);
  assert.equal(issueA.value.number, 'INV-2025-0001');

  const issueB = issueInvoice(invoiceB, [issueA.value.number]);
  assert.equal(issueB.value.number, 'INV-2026-0001');
});

