test('createInvoice rejects non-numeric discountPercent', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 'ten' }],
